insert into quizzes (id, course_id, chapter_id, title, kind, xp_reward, sort) values ('51780471-a63a-5445-aeff-15f6e054e372', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', 'Chapter 1 quiz', 'quiz', 60, 0) on conflict (id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('93fbf93e-3e59-53cc-a0c2-957f87ae1a37', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'What is the accounting equation?', '["Liabilities = Assets + Capital","Assets = Capital − Liabilities","Capital = Assets + Liabilities","Assets = Capital + Liabilities"]'::jsonb, 'Assets = Capital + Liabilities. Everything the business owns (assets) was paid for either by the owner (capital) or by outsiders (liabilities), so the two sides always balance.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('93fbf93e-3e59-53cc-a0c2-957f87ae1a37', 3) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('bd509cb8-9474-5a3d-abc1-b8357a076463', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'A business has assets of $50 000 and liabilities of $18 000. What is the capital?', '["$68 000","$18 000","$32 000","$50 000"]'::jsonb, 'Rearrange the equation: Capital = Assets − Liabilities = $50 000 − $18 000 = $32 000. Adding them together ($68 000) is the usual mistake.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('bd509cb8-9474-5a3d-abc1-b8357a076463', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('256effbc-2817-5f6b-a3bf-9de198939b76', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'The owner takes goods for personal use. What happens to the accounting equation?', '["Assets increase, capital decreases","No change","Assets and capital both decrease","Liabilities increase"]'::jsonb, 'Taking goods for personal use is drawings: inventory (an asset) falls and capital falls by the same amount, so the equation still balances. Liabilities don''t change.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('256effbc-2817-5f6b-a3bf-9de198939b76', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('321b9ef3-3c0d-51c4-aa3b-150a52ed0185', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'What is the main purpose of accounting?', '["To calculate tax only","To provide financial information for decision making","To advertise the business","To pay employees"]'::jsonb, 'Accounting records and summarises transactions so the owner, lenders and others can make decisions. Tax and payroll use accounting data, but they aren''t its main purpose.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('321b9ef3-3c0d-51c4-aa3b-150a52ed0185', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7a762a8c-e091-55a7-ab0c-c354bbc2be2e', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'Which of these is a liability?', '["Motor vehicles","Trade payables","Inventory","Trade receivables"]'::jsonb, 'Trade payables are amounts owed to credit suppliers, so they are a liability. Trade receivables, inventory and vehicles are things the business owns: assets.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('7a762a8c-e091-55a7-ab0c-c354bbc2be2e', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ddd7aa95-412c-548e-a6d5-dd21dc1f4eb6', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'Which of these is a non-current asset?', '["Bank overdraft","Premises","Inventory","Trade receivables"]'::jsonb, 'Non-current assets are kept for more than a year to help run the business, like premises. Inventory and receivables are current assets; an overdraft is a liability.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('ddd7aa95-412c-548e-a6d5-dd21dc1f4eb6', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('cb4943ec-0a38-5f2b-a81a-c55afeb8e261', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'The owner pays $5 000 of personal savings into the business bank account. What is the effect?', '["Assets +$5 000 and capital +$5 000","Assets +$5 000 and liabilities +$5 000","Capital +$5 000 and liabilities −$5 000","No effect"]'::jsonb, 'The bank balance (an asset) rises and capital rises, because the owner has invested more in the business.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('cb4943ec-0a38-5f2b-a81a-c55afeb8e261', 0) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('accbdc13-c075-5f1c-a56a-d2051d3ceac6', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'A business buys a machine on credit for $3 000. What is the effect?', '["Assets decrease and liabilities increase","Assets and liabilities both increase by $3 000","Assets and capital both increase by $3 000","Capital decreases by $3 000"]'::jsonb, 'Machinery (an asset) goes up and the business now owes the supplier $3 000 (a liability). Capital is unchanged.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('accbdc13-c075-5f1c-a56a-d2051d3ceac6', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2cd2ba4f-51c2-536e-a5c5-914b375d8de0', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'Assets are $72 000 and capital is $45 000. What are the liabilities?', '["$72 000","$117 000","$27 000","$45 000"]'::jsonb, 'Liabilities = Assets − Capital = $72 000 − $45 000 = $27 000.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('2cd2ba4f-51c2-536e-a5c5-914b375d8de0', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e062247c-0cc6-55ef-a7e3-9d9e95cba9db', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'A credit customer pays $400 into the business bank account. What happens to the accounting equation?', '["Assets and capital both rise","Liabilities fall","Bank rises and trade receivables fall; totals unchanged","Capital falls"]'::jsonb, 'One asset (bank) goes up and another asset (trade receivables) goes down by the same amount, so totals don''t change.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('e062247c-0cc6-55ef-a7e3-9d9e95cba9db', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2ff59553-1159-5f2b-a8af-eaa280d9b28e', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'The business pays a credit supplier $1 200 from its bank account. What happens?', '["Assets and liabilities both fall by $1 200","Liabilities rise by $1 200","Assets and capital both fall by $1 200","No change"]'::jsonb, 'The bank balance (asset) falls and the amount owed to the supplier (liability) falls by the same amount.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('2ff59553-1159-5f2b-a8af-eaa280d9b28e', 0) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a48c85fd-7aee-56cb-a6a4-9813c6412f43', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'Book-keeping is best described as…', '["Setting selling prices","Checking another firm''s accounts","Recording financial transactions in the books","Interpreting financial statements"]'::jsonb, 'Book-keeping is the detailed day-to-day recording. Accounting goes further: summarising, presenting and interpreting the information.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('a48c85fd-7aee-56cb-a6a4-9813c6412f43', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('64cd117b-afcd-5a58-a883-7ac3fd994165', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'What does ''capital'' mean in accounting?', '["Money owed by customers","Total assets","Cash in the bank","The owner''s investment in the business"]'::jsonb, 'Capital is what the owner has put into the business (plus profits kept in it). The business treats it as owed back to the owner.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('64cd117b-afcd-5a58-a883-7ac3fd994165', 3) on conflict (question_id) do nothing;
