insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a1c44493-a14e-5a23-a652-35ba9f3ca855', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'Goods bought on credit from Ali. Which entries are made?', '["Debit purchases, credit Ali","Debit Ali, credit purchases","Debit purchases, credit cash","Debit inventory, credit sales"]'::jsonb, 'Purchases (an expense) increase, so debit purchases. Ali is now owed money, so his account (a liability) is credited. No cash moves because it was on credit.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('a1c44493-a14e-5a23-a652-35ba9f3ca855', 0) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('94abff21-0e55-5b9d-a6ea-331af0ee724e', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'Which document is sent by a seller to correct an overcharge or for goods returned?', '["Debit note","Statement of account","Invoice","Credit note"]'::jsonb, 'A credit note is issued by the seller to reduce what the customer owes, e.g. for returns or an overcharge. An invoice charges for goods; a statement summarises the account.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('94abff21-0e55-5b9d-a6ea-331af0ee724e', 3) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e14d3a92-0d3a-550f-ad8d-c33d95790746', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'In which book of prime entry are credit sales recorded?', '["Sales journal","Purchases journal","Cash book","General journal"]'::jsonb, 'Credit sales are recorded from sales invoices, which are listed in the sales journal. Cash sales go in the cash book.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('e14d3a92-0d3a-550f-ad8d-c33d95790746', 0) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('bcf23eb0-ea6e-5fdd-a839-3aaf22c2f7b8', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'A cash discount allowed to a customer is recorded as…', '["Debit customer, credit discount allowed","Debit discount allowed, credit customer","Only in the sales journal","Debit cash, credit sales"]'::jsonb, 'Discount allowed is an expense for the seller, so debit discount allowed. The customer now owes less, so credit the customer''s account.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
