insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('bb4948f0-0352-53fe-a66e-f8f89fc09d39', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'Cash sales of $250. Which entries are made?', '["Debit cash, credit sales","Debit sales, credit cash","Debit customer, credit sales","Debit cash, credit customer"]'::jsonb, 'Cash (an asset) increases, so debit cash. Sales (income) increase, so credit sales. No customer account is needed for cash sales.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
