insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a8d0011f-1e77-56e4-a541-c9897c0019c6', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A machine costs $20 000 and is depreciated at 25% per year on the reducing balance. What is the depreciation in year 2?', '["$4 000","$3 750","$2 500","$5 000"]'::jsonb, 'Reducing balance applies the % to the net book value. Year 1: 25% × $20 000 = $5 000, leaving $15 000. Year 2: 25% × $15 000 = $3 750. $5 000 would be straight-line.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
