insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('4594c3e7-735e-5434-a88d-c1ccc9f1447a', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Rent of $1 200 is owed at the year end. How is it shown?', '["Other payable (accrual) and added to the rent expense","Not shown","Deducted from rent expense","Other receivable"]'::jsonb, 'Rent owed is an accrued expense: add it to the rent charged in the income statement and show it as an other payable (a current liability).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('4594c3e7-735e-5434-a88d-c1ccc9f1447a', 0) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f1b0d386-4f84-56d7-a14d-41dfb18599fb', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Inventory should be valued at…', '["The higher of cost and NRV","Replacement cost","The lower of cost and net realisable value","Selling price"]'::jsonb, 'Prudence says inventory must not be overstated, so it is valued at whichever is lower: cost or net realisable value (selling price less costs to sell).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('f1b0d386-4f84-56d7-a14d-41dfb18599fb', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('239fb59b-a28f-5789-a0eb-b61bc8cead70', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'An increase in the allowance for irrecoverable debts is…', '["Income","Added to trade receivables","A liability only","An expense in the income statement"]'::jsonb, 'A bigger allowance for irrecoverable debts reduces profit, so the increase is an expense. The allowance itself is deducted from trade receivables.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('239fb59b-a28f-5789-a0eb-b61bc8cead70', 3) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f42e87e5-77ea-5b04-a223-eb56d8c8af68', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A machine cost $12 000, has a residual value of $2 000 and a useful life of 5 years. Annual straight-line depreciation is…', '["$2 800","$2 000","$1 600","$2 400"]'::jsonb, 'Straight-line = (cost − residual value) ÷ useful life = ($12 000 − $2 000) ÷ 5 = $2 000 a year.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('f42e87e5-77ea-5b04-a223-eb56d8c8af68', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('30020dad-7e1f-5827-a423-aa67fc2aae88', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Which is revenue expenditure?', '["Repainting the office","Buying a delivery van","Legal fees for buying premises","Building an extension"]'::jsonb, 'Repainting maintains an existing asset, so it is a running cost. The others create or improve non-current assets (capital expenditure).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
