insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('971d7e26-c48f-5950-a294-de9e4514dfb9', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A machine with a net book value of $3 500 is sold for $3 000. The result is…', '["A profit on disposal of $500","A loss of $3 000","A loss on disposal of $500","No profit or loss"]'::jsonb, 'It sold for less than its book value: $3 000 − $3 500 = −$500, a loss on disposal.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('971d7e26-c48f-5950-a294-de9e4514dfb9', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3c5ac650-aca7-5685-ad08-50310b9a61db', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Insurance of $900 was paid for 12 months from 1 October. The year ends on 31 December. How much is prepaid at the year end?', '["$675","$300","$225","$900"]'::jsonb, '$900 ÷ 12 = $75 a month. October–December (3 months, $225) belongs to this year; the other 9 months ($675) is a prepayment.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
