insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('08922138-da7a-5ad4-a4a6-6d51b758548d', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A customer who owes $250 is declared bankrupt and will not pay. Which entries are made?', '["Debit irrecoverable debts, credit the customer","Debit allowance, credit sales","Debit the customer, credit irrecoverable debts","Debit sales, credit bank"]'::jsonb, 'The debt is written off: the expense (irrecoverable debts) is debited and the customer''s account is credited to clear it.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
