insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('57835b44-c20e-55b5-a0a3-dfdfedb29343', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Trade receivables are $20 000. The allowance for irrecoverable debts is to be 3%. What is the allowance?', '["$300","$6 000","$600","$60"]'::jsonb, '3% × $20 000 = $600. It is deducted from trade receivables on the statement of financial position.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('57835b44-c20e-55b5-a0a3-dfdfedb29343', 2) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f3a10702-1279-51af-a834-b836fbd06b6c', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Damaged goods cost $800. After repairs costing $100 they can be sold for $600. At what value should they be included in inventory?', '["$600","$500","$800","$700"]'::jsonb, 'Net realisable value = $600 − $100 = $500. This is lower than cost ($800), so inventory is valued at $500.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
