insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3492ad43-313c-5405-a051-6e730b99852a', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Opening capital $30 000, closing capital $38 000, drawings $5 000, no new capital. What is the profit?', '["$8 000","$43 000","$3 000","$13 000"]'::jsonb, 'Profit = closing capital − opening capital + drawings − capital introduced = $38 000 − $30 000 + $5 000 = $13 000. Drawings are added back because they reduced capital without being a loss.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
