insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0a6ec00a-3256-515e-a102-e0c1231ba67f', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Opening inventory $4 000, purchases $26 000, closing inventory $5 000. Cost of sales is…', '["$27 000","$35 000","$25 000","$21 000"]'::jsonb, 'Cost of sales = opening inventory + purchases − closing inventory = $4 000 + $26 000 − $5 000 = $25 000.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
